import requests
from typing import Union

def discover_parameter(base_url: str, candidates: list = ['text', 'textString', 'input']) -> Union[tuple, None]:
    """
    探测正确的 HTTP 方法和参数名。
    返回 (method, param_name) 或 None。
    """
    injection_marker = 'INJECTED_MARKER_12345'
    for param in candidates:
        # 尝试 GET
        try:
            r = requests.get(base_url, params={param: injection_marker}, timeout=5)
            if injection_marker in r.text:
                return ('GET', param)
        except Exception:
            pass
        # 尝试 POST
        try:
            r = requests.post(base_url, data={param: injection_marker}, timeout=5)
            if injection_marker in r.text:
                return ('POST', param)
        except Exception:
            pass
    return None

